def execute(parent_pos=None, item_names=None):
    """
    Invalidate selected Purchase Orders or specific PO Items.
    Sets custom_po_flag = 0 for the selected records.
    Works even for submitted (docstatus=1) POs.
    """

    updated_items, updated_pos = [], []

    # --- normalize inputs safely ---
    if isinstance(parent_pos, str):
        try:
            parent_pos = json.loads(parent_pos)
        except Exception:
            parent_pos = [p.strip() for p in parent_pos.split(",") if p.strip()]

    if isinstance(item_names, str):
        try:
            item_names = json.loads(item_names)
        except Exception:
            item_names = [i.strip() for i in item_names.split(",") if i.strip()]

    # --- invalidate specific items ---
    if item_names:
        for item_name in item_names:
            if not item_name:
                continue
            frappe.db.set_value(
                "Purchase Order Item",
                item_name,
                "custom_po_flag",
                0,
                update_modified=False
            )
            updated_items.append(item_name)

    # --- invalidate full Purchase Orders ---
    if parent_pos:
        for po_name in parent_pos:
            po_name = po_name.strip()
            if not po_name:
                continue

            try:
                po = frappe.get_doc("Purchase Order", po_name)
            except frappe.DoesNotExistError:
                continue

            # only for submitted POs
            if po.docstatus != 1:
                continue

            # set flag for all child rows
            frappe.db.sql("""
                UPDATE `tabPurchase Order Item`
                SET custom_po_flag = 0
                WHERE parent = %s
            """, (po_name,))

            # set flag for parent doc too
            frappe.db.set_value(
                "Purchase Order",
                po_name,
                "custom_po_flag",
                0,
                update_modified=False
            )

            updated_pos.append(po_name)

    frappe.db.commit()

    # --- build final message ---
    message = f"Invalidated {len(updated_pos)} PO(s) and {len(updated_items)} item(s)."

    frappe.logger().info({
        "event": "po_invalidation",
        "updated_pos": updated_pos,
        "updated_items": updated_items
    })

    return {
        "message": message,
        "updated_pos": updated_pos,
        "updated_items": updated_items
    }

