@frappe.whitelist()
def sync_po_links_to_pr(pr_name):
    """
    Sync missing Purchase Order → Purchase Order Item links on Purchase Receipt.
    Runs automatically after 'Get Items from Purchase Order' button is used.
    """

    if not pr_name:
        frappe.throw("Purchase Receipt name is required.")

    pr = frappe.get_doc("Purchase Receipt", pr_name)
    updated = 0

    for row in pr.items:
        # Only fix if PO is set but POI missing
        if row.purchase_order and not row.purchase_order_item:
            poi_name = frappe.db.get_value(
                "Purchase Order Item",
                {"parent": row.purchase_order, "item_code": row.item_code,"item_group":row.item_group},
                "name"
            )
            if poi_name:
                row.purchase_order_item = poi_name
                updated += 1

    if updated:
        pr.save(ignore_permissions=True)
        frappe.db.commit()
        frappe.msgprint(f"Linked {updated} missing Purchase Order Item(s).")
    else:
        frappe.msgprint("All Purchase Order links already complete.")

    return updated

