    bans = frappe.get_all(
        "Add BAN",
        filters={"status": "Active"},
        fields=[
            "ban_type",
            "link_part_number",
            "date_code",
            "manufacturer",
            "quality"
        ]
    )

    messages = []

    for row in doc.items:
        for ban in bans:

            if ban.ban_type == "Part Number BAN" and ban.link_part_number == row.item_code:
                messages.append(f"🚫 Item {row.item_code} is BANNED")

            elif ban.ban_type == "Date Code BAN" and ban.date_code == row.custom_date_code:
                messages.append(f"🚫 Date Code {ban.date_code} is BANNED")

            elif ban.ban_type == "Manufacturer BAN" and ban.manufacturer == row.manufacturer:
                messages.append(f"🚫 Manufacturer {ban.manufacturer} is BANNED")

            elif ban.ban_type == "MFR + Date Code BAN":
                if ban.manufacturer == row.manufacturer and ban.date_code == row.custom_date_code:
                    messages.append("🚫 Manufacturer + Date Code combination is BANNED")

            elif ban.ban_type == "Quality BAN" and ban.quality == row.custom_quality:
                messages.append(f"🚫 Quality {ban.quality} is BANNED")

    if messages:
        frappe.msgprint(
            "<br>".join(set(messages)),
            title="⚠️ BAN Warning",
            indicator="orange"
        )

project = frappe.get_doc("Project", doc.project)

rows = [r for r in project.custom_warehouse_priority if r.enabled]
stocks = list(set(r.stock for r in rows))

effective_stocks = stocks
if stocks == ["Flight-G1"]:
    effective_stocks = ["Flight-G1", "To-Screen"]

if doc.derived_stock_grade not in effective_stocks:
    frappe.throw(
        "Invalid Stock Grade for this Project"
    )

# Enforce To-Screen eligibility based on Component Type (Table-1)

if doc.component and doc.derived_stock_grade:

    if doc.derived_stock_grade == "To-Screen":

        item = frappe.get_doc("Item", doc.component)

        if not item.to_screen_allowed:
            frappe.throw(
                "To-Screen is not applicable for this Component"
            )

if doc.ban_type == "Manufacturer BAN":

    if not doc.manufacturer:
        frappe.throw("Manufacturer is required for Manufacturer BAN")

    rows = frappe.db.sql(
        """
        SELECT DISTINCT item_code
        FROM `tabItem Manufacturer`
        WHERE manufacturer = %s
        """,
        (doc.manufacturer,),
        as_list=True
    )

    if not rows:
        frappe.throw("No Items found for the selected Manufacturer")

    for (item_code,) in rows:
        frappe.db.set_value("Item", item_code, "disabled", 1)

    frappe.msgprint(
        f"All Items for Manufacturer {doc.manufacturer} have been BANNED successfully"
    )

siv_request_type = frappe.form_dict.get("siv_request_type")

if siv_request_type == "Normal Request":
    doctype = "SIV Normal Request"

elif siv_request_type == "Specific Request":
    doctype = "SIV Specific Request"

else:
    frappe.response["message"] = []
    doctype = None

if doctype:
    frappe.response["message"] = frappe.get_all(
        doctype,
        filters={
            "docstatus": 1,
            "status": "Approved"   # ✅ correct for workflow
        },
        pluck="name",
        order_by="creation desc"
    )
